import {defaults,normalize,encodeConfig,decodeConfig} from './config.mjs';
const $=id=>document.getElementById(id);
let config={...defaults},stage='arrival',shared=false,toastTimer,holding=false,holdStart=0,holdFrame=0,completionTimer=0,wishPower=0;
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
try{const imported=decodeConfig(location.hash);if(imported){config=imported;shared=true;}else{config=normalize(JSON.parse(localStorage.getItem('moonlit-draft')||'null'));}}catch{setTimeout(()=>toast('这份链接或草稿未能读取，已打开默认来信。'),600);}
function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3300);}
function applyConfig(){document.body.dataset.tone=config.tone;$('arrival-title').textContent=config.title;$('intro-copy').textContent=config.intro;$('letter-recipient').textContent=config.recipient+'：';$('letter-body').textContent=config.letter;$('letter-sender').textContent=config.sender;$('ending-recipient').textContent=config.recipient;$('ending-copy').textContent=config.ending;$('ending-sender').textContent=config.sender;document.title=`月光来信 · 给${config.recipient}的生日祝福`;if(shared)$('edit-button').hidden=true;}
function go(next){if(!['arrival','letter','wish','ending'].includes(next))return;stopHold();clearTimeout(completionTimer);wishPower=0;stage=next;document.body.dataset.stage=stage;for(const id of ['arrival','letter','wish','ending'])$(id).hidden=id!==stage;const active=stage==='ending'?'wish':stage;document.querySelectorAll('[data-go]').forEach(button=>{if(button.dataset.go===active)button.setAttribute('aria-current','step');else button.removeAttribute('aria-current');});$('stage-count').textContent=({arrival:'01',letter:'02',wish:'03',ending:'03'})[stage]+' — 03';$('hold-wish').disabled=false;$('hold-label').textContent='按住许愿';$('wish-status').textContent='让心愿在掌心停留 3 秒';$('simple-wish').disabled=false;window.scrollTo({top:0,behavior:'instant'});const heading=$(stage).querySelector('h1,h2');heading.setAttribute('tabindex','-1');heading.focus({preventScroll:true});if(stage==='ending'){burst=performance.now();chime();}}
$('open-letter').addEventListener('click',()=>{chime();go('letter');});$('to-wish').addEventListener('click',()=>go('wish'));$('replay').addEventListener('click',()=>go('arrival'));document.querySelectorAll('[data-go]').forEach(button=>button.addEventListener('click',()=>go(button.dataset.go)));document.querySelector('.brand').addEventListener('click',event=>{event.preventDefault();go('arrival');});
const editor=$('editor'),form=$('editor-form');
function openEditor(){stopHold();for(const key of ['recipient','sender','title','intro','letter','ending'])form.elements[key].value=config[key];form.elements.tone.value=config.tone;form.elements.particles.checked=config.particles;$('share-result').hidden=true;editor.showModal();}
function closeEditor(){editor.close();}
function formConfig(){if(!form.reportValidity())return null;const value=Object.fromEntries(new FormData(form));value.particles=form.elements.particles.checked;return normalize(value);}
function save(value){config=value;try{localStorage.setItem('moonlit-draft',JSON.stringify(config));}catch{toast('当前浏览器无法保存草稿，本次预览仍然有效。');}if(shared){history.replaceState(null,'',location.pathname+location.search);shared=false;$('edit-button').hidden=false;}applyConfig();}
$('edit-button').addEventListener('click',openEditor);$('ending-edit').addEventListener('click',openEditor);$('close-editor').addEventListener('click',closeEditor);editor.addEventListener('click',event=>{if(event.target===editor){const r=editor.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeEditor();}});form.addEventListener('submit',event=>{event.preventDefault();const value=formConfig();if(!value)return;save(value);closeEditor();go('arrival');toast('你的心意，已经写进月光里。');});
$('share-button').addEventListener('click',()=>{const value=formConfig();if(!value)return;save(value);const url=new URL(location.href);url.hash='letter='+encodeConfig(config);$('share-url').value=url.href;$('share-result').hidden=false;$('share-result').scrollIntoView({behavior:reduced.matches?'instant':'smooth',block:'nearest'});});
$('copy-link').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('share-url').value);toast('祝福链接已复制。');}catch{$('share-url').focus();$('share-url').select();toast('请复制选中的祝福链接。');}});
function stopHold(){holding=false;cancelAnimationFrame(holdFrame);$('hold-wish').classList.remove('holding');$('hold-wish').querySelector('circle').style.strokeDashoffset='427.26';if(stage==='wish'&&!$('hold-wish').disabled){$('hold-label').textContent='按住许愿';wishPower=0;}}
function completeWish(){if(stage!=='wish'||$('hold-wish').disabled)return;stopHold();$('hold-wish').disabled=true;$('simple-wish').disabled=true;$('hold-label').textContent='愿望已送达';$('wish-status').textContent='这一刻，月光也在为你祝福。';$('hold-wish').querySelector('circle').style.strokeDashoffset='0';wishPower=1;chime();completionTimer=setTimeout(()=>go('ending'),reduced.matches?200:1350);}
function startHold(){if(stage!=='wish'||holding||$('hold-wish').disabled)return;holding=true;holdStart=performance.now();$('hold-wish').classList.add('holding');$('hold-label').textContent='让心愿发光';const tick=now=>{if(!holding)return;wishPower=Math.min((now-holdStart)/3000,1);$('hold-wish').querySelector('circle').style.strokeDashoffset=String(427.26*(1-wishPower));if(wishPower>=1)completeWish();else holdFrame=requestAnimationFrame(tick);};holdFrame=requestAnimationFrame(tick);}
$('hold-wish').addEventListener('pointerdown',event=>{if(event.button!==0)return;event.preventDefault();$('hold-wish').setPointerCapture(event.pointerId);startHold();});for(const name of ['pointerup','pointercancel','lostpointercapture'])$('hold-wish').addEventListener(name,stopHold);$('hold-wish').addEventListener('keydown',event=>{if(event.code==='Space'||event.code==='Enter'){event.preventDefault();if(!event.repeat)startHold();}});$('hold-wish').addEventListener('keyup',event=>{if(event.code==='Space'||event.code==='Enter'){event.preventDefault();stopHold();}});$('hold-wish').addEventListener('blur',stopHold);$('simple-wish').addEventListener('click',completeWish);window.addEventListener('blur',stopHold);
let audioContext=null,audioGain=null,soundOn=false,tones=[];
async function toggleSound(){try{if(!audioContext){audioContext=new AudioContext();audioGain=audioContext.createGain();audioGain.gain.value=0;audioGain.connect(audioContext.destination);[130.81,196,261.63,329.63].forEach((frequency,index)=>{const oscillator=audioContext.createOscillator(),gain=audioContext.createGain();oscillator.type='sine';oscillator.frequency.value=frequency;gain.gain.value=.045/(index+1);oscillator.connect(gain);gain.connect(audioGain);oscillator.start();tones.push(oscillator);});}soundOn=!soundOn;if(soundOn)await audioContext.resume();audioGain.gain.setTargetAtTime(soundOn?.45:0,audioContext.currentTime,.6);$('sound-button').setAttribute('aria-pressed',String(soundOn));$('sound-button').setAttribute('aria-label',soundOn?'关闭环境音':'开启环境音');$('sound-label').textContent=soundOn?'声音开':'声音关';if(soundOn)chime();}catch{soundOn=false;toast('当前浏览器暂时无法播放声音。');}}
function chime(){if(!soundOn||!audioContext)return;[523.25,659.25,783.99].forEach((frequency,index)=>{const o=audioContext.createOscillator(),g=audioContext.createGain(),t=audioContext.currentTime+index*.22;o.type='sine';o.frequency.value=frequency;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.085,t+.04);g.gain.exponentialRampToValueAtTime(.001,t+2.2);o.connect(g);g.connect(audioGain);o.start(t);o.stop(t+2.3);});}
$('sound-button').addEventListener('click',toggleSound);document.addEventListener('visibilitychange',()=>{if(document.hidden){stopHold();audioContext?.suspend();}else if(soundOn)audioContext?.resume().catch(()=>{});});
const canvas=$('fireflies'),ctx=canvas.getContext('2d');let width=innerWidth,height=innerHeight,burst=0,lastFrame=0;const motes=Array.from({length:70},()=>({x:Math.random(),y:Math.random(),r:.6+Math.random()*1.4,speed:.2+Math.random()*.6,phase:Math.random()*Math.PI*2}));
function resize(){width=innerWidth;height=innerHeight;const ratio=Math.min(devicePixelRatio||1,1.7);canvas.width=width*ratio;canvas.height=height*ratio;ctx?.setTransform(ratio,0,0,ratio,0,0);}
window.addEventListener('resize',resize);resize();function animate(time){requestAnimationFrame(animate);if(!ctx||time-lastFrame<32)return;lastFrame=time;ctx.clearRect(0,0,width,height);if(document.hidden||!config.particles||reduced.matches)return;const t=time*.00015;for(const [index,m] of motes.entries()){let x=((m.x+Math.sin(t*m.speed+m.phase)*.025+1)%1)*width,y=((m.y-t*m.speed*.018+2)%1)*height;const intensity=.25+.55*(.5+.5*Math.sin(t*4+m.phase));if(wishPower>0){x+=(width*.5-x)*wishPower*.75;y+=(height*.5-y)*wishPower*.75;}if(stage==='ending'&&time-burst<5000){const p=(time-burst)/5000;x=width*.5+Math.cos(m.phase)*(width*.15+p*width*.5)*m.speed;y=height*.47+Math.sin(m.phase)*(height*.1+p*height*.45)*m.speed;}ctx.beginPath();ctx.fillStyle=`rgba(246,218,157,${intensity})`;ctx.shadowBlur=8;ctx.shadowColor='#f8d592';ctx.arc(x,y,m.r,0,Math.PI*2);ctx.fill();}ctx.shadowBlur=0;}
applyConfig();requestAnimationFrame(animate);
if(document.modelContext?.registerTool){try{const registration=document.modelContext.registerTool({name:'read_birthday_configuration',title:'读取生日来信配置',description:'读取当前页面可见的来信内容、氛围和体验阶段，不修改内容。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({stage,configuration:{...config}})});Promise.resolve(registration).catch(()=>{});}catch{}}
